using SkiaSharp;
using System.Text.Json;
var output=args[0];Directory.CreateDirectory(output);var values=new Dictionary<string,object?>();var cases=new List<object>();using var pixels=File.Create(Path.Combine(output,"pixels.bin"));int checks=0;
for(int seedIndex=0;seedIndex<3;seedIndex++)for(int fractal=0;fractal<2;fractal++)for(int octavesIndex=0;octavesIndex<3;octavesIndex++)for(int tile=0;tile<2;tile++)for(int transform=0;transform<4;transform++)
{
    float seed=new[]{0,7.75f,-17.3f}[seedIndex];int octaves=new[]{0,1,4}[octavesIndex];SKSizeI tileSize=tile==0?default:new(32,24);using var original=fractal==1?SKShader.CreatePerlinNoiseFractalNoise(.075f,.12f,octaves,seed,tileSize):SKShader.CreatePerlinNoiseTurbulence(.075f,.12f,octaves,seed,tileSize);
    using var shader=transform==3?original.WithLocalMatrix(SKMatrix.CreateScale(1.3f,.8f)):original.WithLocalMatrix(SKMatrix.Identity);using var surface=SKSurface.Create(new SKImageInfo(32,24,SKColorType.Rgba8888,SKAlphaType.Premul))!;surface.Canvas.Clear(new SKColor(30,40,50));if(transform==1)surface.Canvas.Translate(3.25f,2.75f);if(transform==2){surface.Canvas.Translate(2,1);surface.Canvas.Scale(1.5f,1.2f);}
    using(var paint=new SKPaint{Shader=shader,Color=new SKColor(255,255,255,(byte)(transform==0?255:170))})surface.Canvas.DrawPaint(paint);using var image=surface.Snapshot();using var read=new SKBitmap(new SKImageInfo(32,24,SKColorType.Rgba8888,SKAlphaType.Premul));checks++;if(!image.ReadPixels(read.Info,read.GetPixels(),read.RowBytes))throw new Exception("Read failed");var bytes=read.GetPixelSpan().ToArray();cases.Add(new{kind="perlin",scene=((seedIndex*2+fractal)*3+octavesIndex)*2+tile,transform,offset=pixels.Position,length=bytes.Length});pixels.Write(bytes);
}
foreach(var test in new[]{(-.1f,.1f,1,0f),(.1f,.1f,-1,0f),(.1f,.1f,256,0f),(float.NaN,.1f,1,0f),(.1f,.1f,1,float.PositiveInfinity)}){using var shader=SKShader.CreatePerlinNoiseFractalNoise(test.Item1,test.Item2,test.Item3,test.Item4);values[$"invalid-{values.Count}"]=shader is null;}
File.WriteAllText(Path.Combine(output,"values.json"),JsonSerializer.Serialize(values));File.WriteAllText(Path.Combine(output,"cases.json"),JsonSerializer.Serialize(cases));File.WriteAllText(Path.Combine(output,"local.json"),JsonSerializer.Serialize(new{checks,vector=System.Numerics.Vector.IsHardwareAccelerated}));Console.WriteLine($"Captured {cases.Count} Perlin images, {values.Count} validation entries and {checks} pixel reads");
